<!DOCTYPE html>
<html>
<head>
  <title>Falling Sand</title>
  <style>
    body {
      background-color: #1e1e1e;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
      margin: 0;
      font-family: sans-serif;
    }

    #controls {
      margin-right: 20px;
    }

    button {
      background-color: #333;
      border: none;
      padding: 10px 20px;
      margin: 5px;
      cursor: pointer;
      color: white;
      font-size: 16px;
    }

    button:hover {
      background-color: #555;
    }

    #canvas {
      border: 1px solid #444;
      background-color: #222;
      display: block;
    }
  </style>
</head>
<body>

  <div id="controls">
    <button id="mat-sand">Sand</button>
    <button id="mat-water">Water</button>
    <button id="mat-wall">Wall</button>
    <button id="mat-acid">Acid</button>
    <button id="mat-empty">Empty (Eraser)</button>
    <button id="clear">Clear</button>
  </div>

  <canvas id="canvas"></canvas>

  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const w = 80;
    const h = 80;
    let grid = [];

    // Initialize grid with empty cells
    for (let y = 0; y < h; y++) {
      grid[y] = [];
      for (let x = 0; x < w; x++) {
        grid[y][x] = 'empty';
      }
    }

    window.sim = {
      w,
      h,
      tick: function(n) {
        for (let i = 0; i < n; i++) {
          simulate();
        }
      },
      get: function(x, y) {
        if (y < 0 || y >= h || x < 0 || x >= w) return 'wall';
        return grid[y][x];
      },
      set: function(x, y, material) {
        if (y < 0 || y >= h || x < 0 || x >= w) return;
        grid[y][x] = material;
      },
      clear: function() {
        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            grid[y][x] = 'empty';
          }
        }
      }
    };

    function simulate() {
      // Check for boundaries and place materials
      for (let y = h - 1; y >= 0; y--) {
        for (let x = 0; x < w; x++) {
          if (window.sim.get(x, y) === 'sand') {
            // Try to move down
            if (y + 1 < h && window.sim.get(x, y + 1) === 'empty') {
              window.sim.set(x, y + 1, 'sand');
              window.sim.set(x, y, 'empty');
            } else if (y + 1 < h && window.sim.get(x, y + 1) !== 'empty') {
              // Slide diagonally down-left or right
              const direction = Math.random() < 0.5 ? -1 : 1;
              if (x + direction >= 0 && x + direction < w && window.sim.get(x + direction, y + 1) === 'empty') {
                window.sim.set(x + direction, y + 1, 'sand');
                window.sim.set(x, y, 'empty');
              }
            }
          }

          if (window.sim.get(x, y) === 'water') {
            // Spread horizontally
            for (let dx = -1; dx <= 1; dx++) {
              if (x + dx >= 0 && x + dx < w && y < h && window.sim.get(x + dx, y) === 'empty') {
                window.sim.set(x + dx, y, 'water');
                window.sim.set(x, y, 'empty');
              }
            }
          }

          if (window.sim.get(x, y) === 'acid') {
            // Dissolve sand and walls
            for (let dx = -1; dx <= 1; dx++) {
              for (let dy = -1; dy <= 1; dy++) {
                const nx = x + dx;
                const ny = y + dy;

                if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
                  if (window.sim.get(nx, ny) === 'sand' || window.sim.get(nx, ny) === 'wall') {
                    window.sim.set(nx, ny, 'empty'); // Or just 'empty' if you prefer
                  }
                }
              }
            }
          }
        }
      }
    }

    canvas.width = w * 20;
    canvas.height = h * 20;

    function draw() {
      ctx.fillStyle = '#222';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const material = window.sim.get(x, y);
          const colorMap = {
            'empty': '#333',
            'sand': '#808000',
            'water': '#00FFFF',
            'wall': '#AAAAAA',
            'acid': '#FF0000'
          };

          ctx.fillStyle = colorMap[material];
          ctx.fillRect(x * 20, y * 20, 20, 20);
        }
      }
    }


    draw(); // Initial draw

    document.getElementById('mat-sand').addEventListener('click', () => window.sim.set(0, 0, 'sand'));
    document.getElementById('mat-water').addEventListener('click', () => window.sim.set(0, 0, 'water'));
    document.getElementById('mat-wall').addEventListener('click', () => window.sim.set(0, 0, 'wall'));
    document.getElementById('mat-acid').addEventListener('click', () => window.sim.set(0, 0, 'acid'));
    document.getElementById('mat-empty').addEventListener('click', () => window.sim.set(0, 0, 'empty'));
    document.getElementById('clear').addEventListener('click', () => window.sim.clear());

    function animate() {
      window.sim.tick(1); // Advance the simulation by one step
      draw();
      requestAnimationFrame(animate);
    }

    animate();
  </script>

</body>
</html>
